/**
 * OpenMAIC 中文课堂讲稿风格语料。
 *
 * 这些文本是风格示范，不是事实来源。生产提示词只能迁移课堂话语动作、节奏和语气，
 * 绝不能把示例中的人物、数字、公式或学科结论带入当前课程。
 */

export const NARRATION_TEACHING_MOVES = [
  'hook',
  'course_orientation',
  'attention_guidance',
  'concept_explanation',
  'analogy',
  'mechanism_or_formula',
  'evidence_reasoning',
  'misconception_contrast',
  'observation_prompt',
  'practice_transition',
  'post_quiz_bridge',
  'post_interactive_bridge',
  'section_transition',
  'project_instruction',
  'synthesis_transfer',
] as const;

export type NarrationTeachingMove = (typeof NARRATION_TEACHING_MOVES)[number];
export type NarrationExampleSceneType = 'slide' | 'quiz' | 'interactive';
export type NarrationExamplePagePosition = 'first' | 'middle' | 'last';
export type NarrationExampleDiscipline = 'language' | 'science' | 'engineering';
export type NarrationExampleExclusionReason =
  | 'multiple-speakers'
  | 'duplicate-greeting'
  | 'invented-learner-performance'
  | 'overused-template'
  | 'content-specific-risk';

export interface NarrationStyleExample {
  readonly id: string;
  readonly sourceCourse: string;
  readonly sourceTitle: string;
  readonly discipline: NarrationExampleDiscipline;
  readonly sourcePage: number;
  readonly sceneType: NarrationExampleSceneType;
  readonly pagePosition: NarrationExamplePagePosition;
  readonly precedingSceneType?: NarrationExampleSceneType;
  readonly teachingMoves: readonly NarrationTeachingMove[];
  readonly styleStrengths: readonly string[];
  readonly exampleText: string;
  readonly highlightExcerpt: string;
  readonly productionEligible: boolean;
  readonly excludedSpans: ReadonlyArray<{
    readonly text: string;
    readonly reason: NarrationExampleExclusionReason;
  }>;
}

export const OPENMAIC_CHINESE_NARRATION_CORPUS_VERSION =
  'openmaic-chinese-narration-examples/v1' as const;

interface NarrationExamplePageSeed {
  readonly title: string;
  readonly text: string;
  readonly sceneType?: NarrationExampleSceneType;
  readonly teachingMoves?: readonly NarrationTeachingMove[];
  readonly highlightExcerpt?: string;
  readonly excludedSpans?: NarrationStyleExample['excludedSpans'];
}

interface NarrationExampleCourseSeed {
  readonly slug: string;
  readonly title: string;
  readonly discipline: NarrationExampleDiscipline;
  readonly pages: readonly NarrationExamplePageSeed[];
}

