const unique = <T>(values: readonly T[]): readonly T[] => [...new Set(values)];

const inferTeachingMoves = (
  page: NarrationExamplePageSeed,
  pageIndex: number,
  totalPages: number,
): readonly NarrationTeachingMove[] => {
  if (page.teachingMoves !== undefined) return page.teachingMoves;
  const searchable = `${page.title}\n${page.text}`;
  const moves: NarrationTeachingMove[] = [];
  if (pageIndex === 0 || /导入|诞生|旅程/u.test(page.title)) moves.push('hook');
  if (/看|观察|聚焦|注意|图|表|屏幕/u.test(searchable)) moves.push('attention_guidance');
  if (/定义|概念|什么是|核心|组成/u.test(searchable)) moves.push('concept_explanation');
  if (/就像|好比|像一个|旅行|高速公路|心脏|阀门/u.test(searchable)) moves.push('analogy');
  if (/公式|过程|流程|原理|机制|作用|分解/u.test(searchable)) moves.push('mechanism_or_formula');
  if (/证据|说明|证明|推断|结果|结论|对比/u.test(searchable)) moves.push('evidence_reasoning');
  if (/易错|区分|不同|区别|不要混淆|并不是/u.test(searchable)) {
    moves.push('misconception_contrast');
  }
  if (/思考|为什么|怎样|如何|观察|试想|问题/u.test(searchable)) {
    moves.push('observation_prompt');
  }
  if (page.sceneType === 'quiz') moves.push('practice_transition');
  if (page.sceneType === 'interactive') moves.push('observation_prompt', 'practice_transition');
  if (/章节页|第一部分|第二部分|进入.*部分/u.test(searchable)) moves.push('section_transition');
  if (/项目|任务|排演|创作/u.test(searchable)) moves.push('project_instruction');
  if (pageIndex === totalPages - 1 || /小结|总结|回望|迁移|未来/u.test(page.title)) {
    moves.push('synthesis_transfer');
  }
  return unique(moves.length > 0 ? moves : ['concept_explanation']);
};

const styleStrengthsForMoves = (moves: readonly NarrationTeachingMove[]): readonly string[] => {
  const strengths = ['教师直接面向学生', '自然段落与口语换气'];
  if (moves.includes('attention_guidance')) strengths.push('具体组织学生注意力');
  if (moves.includes('analogy')) strengths.push('先用生活化直觉再落到学科表达');
  if (moves.includes('evidence_reasoning')) strengths.push('用证据链解释结论');
  if (moves.includes('misconception_contrast')) strengths.push('主动预判易错点');
  if (moves.includes('observation_prompt')) strengths.push('用有功能的问题邀请观察思考');
  if (moves.includes('project_instruction')) strengths.push('把任务拆成可执行课堂动作');
  if (moves.includes('synthesis_transfer')) strengths.push('具体收束并支持迁移');
  return strengths;
};

const firstSentenceExcerpt = (text: string): string => {
  const match = text.match(/^.{1,180}?[。！？?](?:[”’」』])?/u);
  return (match?.[0] ?? text.slice(0, 180)).trim();
};

const buildCourseExamples = (
  course: NarrationExampleCourseSeed,
): readonly NarrationStyleExample[] =>
  course.pages.map((page, index) => {
    const id = `openmaic-${course.slug}-${String(index + 1).padStart(2, '0')}`;
    const previous = course.pages[index - 1];
    const teachingMoves = inferTeachingMoves(page, index, course.pages.length);
    return {
      id,
      sourceCourse: course.title,
      sourceTitle: page.title,
      discipline: course.discipline,
      sourcePage: index + 1,
      sceneType: page.sceneType ?? 'slide',
      pagePosition: index === 0 ? 'first' : index === course.pages.length - 1 ? 'last' : 'middle',
      ...(previous === undefined ? {} : { precedingSceneType: previous.sceneType ?? 'slide' }),
      teachingMoves,
      styleStrengths: styleStrengthsForMoves(teachingMoves),
      exampleText: page.text,
      highlightExcerpt: page.highlightExcerpt ?? firstSentenceExcerpt(page.text),
      productionEligible: PRODUCTION_CORE_IDS.has(id),
      excludedSpans: page.excludedSpans ?? [],
    } satisfies NarrationStyleExample;
  });

/**
 * 归档原文全集。exampleText 永远保留用户提供的文本；生产注入必须通过
 * renderProductionSafeNarrationExample 剔除明确标注的缺陷片段。
 */
export const OPENMAIC_CHINESE_NARRATION_EXAMPLES: readonly NarrationStyleExample[] =
  COURSE_SEEDS.flatMap(buildCourseExamples);

/**
 * 只删除原文中明确列出的 excludedSpans，不补写、不润色、不拼入新句子。
 * 返回值因此仍然完全由原文片段按原顺序连接而成。
 */
export const renderProductionSafeNarrationExample = (example: NarrationStyleExample): string => {
  let rendered = example.exampleText;
  for (const exclusion of example.excludedSpans) {
    rendered = rendered.split(exclusion.text).join('');
  }
  return rendered.trim();
};

/** 用于完整性测试和审计的稳定序列化，字段顺序属于该摘要合同。 */
export const serializeOpenMaicChineseNarrationCorpus = (): string =>
  OPENMAIC_CHINESE_NARRATION_EXAMPLES.map((example) =>
    [example.id, example.sourceTitle, example.exampleText].join('\n'),
  ).join('\n\n---\n\n');

